-- DNA a partir do deck de marca da propria Casio (G-SHOCK / VINTAGE em acao).
insert into public.marcas (nome, tenant_id, status_varredura, intervalo_horas, yaml_conhecimento) values
  ('Casio Vintage CO', '61863470-3633-4de9-804e-1fb4a2ae6311', true, 24, '{"marca": "Casio Vintage", "pais": "CO", "idioma": "es", "produto": "Linha CASIO Vintage: celebra a heranca da marca com relogios que transcendem geracoes (A168, A158, F-91W, CA-53W calculadora, LA670 dourado). A Casio foi pioneira nesse estilo retro e o design segue atemporal e reconhecivel; producao continua, nao reedicao. Collabs com cultura pop (Stranger Things, De Volta para o Futuro).", "tom": "Atemporal, autentico e simples. Fala do objeto e do que ele conecta entre passado e presente. Nostalgia com lastro, nunca saudosismo.", "perfil_comportamental": "Publico de diferentes idades e estilos (Colombia), com nucleo jovem e urbano que constroi identidade por curadoria: mistura decadas, generos e precos. Circula entre moda, arte, humor e lifestyle; compra em marketplace, streetwear e ropa de segunda. O relogio e acessorio de estilo e ponte entre passado e presente, nao instrumento tecnico nem concorrente de smartwatch.", "universos_culturais": ["Moda e arte (campanha Masterpiece)", "Nostalgia com lastro: games retro, cinema e series dos anos 80 e 90", "Collabs com cultura pop (Stranger Things, De Volta para o Futuro)", "Revival Y2K e estetica dos anos 2000", "Ropa de segunda, tiendas vintage e compraventa", "Fotografia analogica e cameras digitais antigas", "Creators de moda e humor", "Reggaeton e urbano de Medellin, rap colombiano, cena indie de Bogota"], "ambicao_de_marca": "Ser o icone do universo retro: design atemporal que segue relevante independentemente das tendencias, transitando entre moda, cultura e lifestyle como conexao entre passado e presente.", "o_que_evitar": ["posicionar a marca como tendencia passageira: ela e atemporal, independente das tendencias", "tratar a linha como reedicao: ela nunca saiu de linha", "competir em especificacao tecnica com smartwatch", "nostalgia generica, sem lastro no objeto ou numa referencia real", "tom saudosista ou melancolico", "importar referencia brasileira para o mercado local", "tom politico"], "termos_busca": ["Casio vintage", "Casio A168", "F-91W", "reloj Casio retro", "Casio calculadora"], "termos_culturais": ["estetica 2000", "ropa de segunda", "outfit vintage", "videojuegos retro", "peliculas de los 80", "camara digital vieja", "coleccionar relojes", "dejar el smartwatch", "accesorio para el outfit"], "termos_culturais_en": ["Y2K revival", "retro tech", "vintage watch collecting", "casiocore", "analog revival", "80s pop culture"], "dominios_culturais": ["comportamento", "entretenimento", "massa", "moda", "musica"], "peso_cultural": 0.8333333333333334, "linkedin_ativo": false, "perfil_cultural_manual": true, "justificativa_cultural": "Escolha MANUAL (02/10/2026), mercado Colombia. Base: deck de marca da Casio (G-SHOCK / CASIO VINTAGE em acao), recebido em 02/10/2026. Pilares do material: moda, arte, nostalgia e collabs de cultura pop. Moda e o centro; entretenimento entra pela nostalgia (games retro, cinema 80/90) e pelas collabs; comportamento cobre anti-smartwatch; musica e massa pegam cena e viral. Tech saiu: gadget nao e o territorio. 5 de 6 vagas."}'::jsonb),
  ('G-Shock CO', '61863470-3633-4de9-804e-1fb4a2ae6311', true, 24, '{"marca": "G-Shock", "pais": "CO", "idioma": "es", "produto": "G-SHOCK, criado em 1983 por Kikuo Ibe com a missao de ser um relogio praticamente indestrutivel. Mais de 40 anos como icone da cultura urbana, dos esportes de acao e do lifestyle: design marcante, durabilidade extrema, Bluetooth, energia solar e sensores para outdoor. Linhas: DW-5600, GA-2100 (''CasiOak''), Mudmaster/Rangeman, MR-G. Collabs sao pilar estrategico (ex.: Stranger Things, Evangelion): edicoes limitadas com marcas, artistas e personalidades.", "tom": "Atitude, autenticidade e resistencia, os tres valores da marca. Direto e fisico, sem frescura: resistencia como postura, nao como especificacao.", "perfil_comportamental": "Quem vive cultura urbana e esporte de acao em Colombia: skate (Street League Skateboarding), luta e MMA, corrida de rua e comunidade Strava, rap e musica urbana, colecionadores de relogio e de edicao limitada. Referencias de embaixador no Brasil: skatista (Giovanni Vianna), lutador de MMA (Lucas Mineiro), rapper, ator e skatista (L7nnon), colecionador (Caio Victor). O relogio e marcador de tribo e de superacao.", "universos_culturais": ["Skate e Street League (SLS)", "Luta, MMA e treino", "Corrida de rua e comunidade Strava", "Colecionismo de relogio e edicoes limitadas", "Collabs com cultura pop: series, anime, games (Stranger Things, Evangelion)", "Reggaeton e urbano de Medellin, rap colombiano, cena indie de Bogota", "Outdoor e aventura", "Streetwear e sneakers"], "ambicao_de_marca": "Conectar com pessoas, culturas e movimentos que compartilham atitude, autenticidade e resistencia: apoiar quem representa superacao, falar com diferentes geracoes por meio de influenciadores e estar nos eventos e comunidades que movimentam esporte, cultura e comunidade.", "o_que_evitar": ["competir em especificacao com smartwatch", "tom de catalogo tecnico", "masculinidade toxica ou agressividade gratuita", "estetica militar,